def extended_gcd(a, b):
    if b == 0:
        return (1, 0)
    else:
        g, x, y = extended_gcd(b, a % b)
        return (g, y, x - (a // b) * y)

def mod_inverse(a, p):
    g, x, _ = extended_gcd(a, p)
    return (x % p + p) % p  # to get the modular inverse

class Blackboard:
    def __init__(self):
        self.sets = {}

    def add(self, n):
        if n not in self.sets:
            self.sets[n] = 1
        else:
            self.sets[n] += 1

    def remove(self, n):
        if n in self.sets:
            self.sets[n] -= 1

def reduce_to_positive_power_of_two(n, p):
    result = 0
    while n:
        if n % 2 == 1:
            result = mod_inverse(result + pow(2, result, p), p)
        result = mod_inverse(result + pow(2, result, p), p)
        result &= negate(n & 1, p)
        n >>= 1
    return result

def negate(b, p):
    if b == 0:
        return 1
    return pow(2, negate(b - 1, p), p)

def solve(n, x, a):
    blackboard = Blackboard()
    for i in range(n):
        num = reduce_to_positive_power_of_two(int(a[i], 2), 998244353)
        blackboard.add(num)
        if num <= x:
            result = max(0, x - num)
            if result in blackboard.sets:
                result = blackboard.sets[result]
    return result

