def count_hopping_sequences(N, graph, ratings):
    MOD = 10**9 + 7
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    for i in range(1, N + 1):
        dp[i][i] = 1

    for length in range(2, N + 1):
        for start in range(1, N + 1):
            end = start
            while end + 1 <= N and ratings[start - 1] >= ratings[end]:
                end += 1
            for hop in range(start, end + 1):
                if ratings[hop - 1] < ratings[start]:
                    dp[start][end] += dp[start][hop - 1] * dp[hop][end]
                    dp[start][end] %= MOD

    return sum(dp[start][end] for end in range(start, N + 1)) % MOD

