def longest_cool_sequence(name, cool_substrings):
    n = len(name)
    if n <= 1:
        return n
    current_str = deque([name[0]])
    max_length = 1
    for i in range(1, n):
        current_str.append(name[i])
        if len(current_str) == 4 and is_cooler(current_str, cooler_substrings):
