def solve_garden(n, m, k, aij, importance_squares):
    from scipy import optimize

    def road_cost(new_positions):
        position_matrix = np.zeros((n, m))
        for i, j in new_positions:
            x, y = i % m, j % m
            if x:
                position_matrix[i, j] = max(a[i // m, j], a[i % m, j])
            if y:
                position_matrix[i, j] = max(a[i, j // m], a[i, j % m])
        discount = np.mean(position_matrix)
        return discount

    result_positions = optimize.minimize(road_cost, importance_squares, method='Nelder-Mead').x
    return road_cost(result_positions)

