from collections import deque

def solve(s):
    stack = deque()
    for char in s:
        if char == '?':
            stack.append('?')
        elif char == '(' or char == ')':
            stack.append(char)
        elif char == '+':
            if not stack or stack.pop() == '?':
                if not stack or stack.pop() != '?':
                    stack.append('?')
                else:
                    stack.append('+')
        elif char == '-':
            if not stack or stack.pop() == '?':
                if not stack or stack.pop() != '?':
                    stack.append('?')
                else:
                    stack.append('-')
        else:
            raise ValueError(f"Unexpected character: {char}")
    return stack

def power_of_substring(s, l, r):
    s = solve(s[:l-1]) + s[l:r+1] + solve(s[r+1:])[::-1]
    return int(s)

