def find_discrepancies(B):
    # Initialize the discrepancies
    differences = [0] * len(B)

    # Calculate the discrepancies
    if B[-1] > B[0]:
        differences[-1] = 2 * (B[0] - B[-1]) + 1
    else:
        differences[-1] = 2 * (B[-1] - B[0]) + 1 - 2

    for i in range(len(B) - 2, -1, -1):
        if B[i] > B[i + 1]:
            differences[i] = 2 * (B[i + 1] - B[i])
        else:
            differences[i] = 2 * (B[i] - B[i + 1]) + 2

    return differences

def count_valid_arrays(B):
    N = len(B) + 1
    # Add initial differences
    differences = [0] * N
    differences[-1] = N - 2

    # Create an array of discrepancies
    discrepancies = []
    for i in range(N - 2):
        if differences[i] > 0 and differences[i + 1] < 0:
            discrepancies.append((differences[i] + differences[i + 1]) % (10**9 + 7))

    # Sort discrepancies
    discrepancies = sorted(discrepancies, key=lambda x: (x, abs(x)))

    # Directly return all the possible values modulo 10^9 + 7
    return [(a, b) for (a, b) in zip(differences, discrepancies)]
