def solve_tree(n, parents):
    # Initialize the parent map for speed
    parent_map = defaultdict(set)
    for parent, child in enumerate(parents):
        parent_map[parent].add(child)

    # Initialize the tree representation
    tree = [0] * n

    # Build the tree by following the chain of parents
    parent_start = None
    for parent, child in enumerate(parents):
        if not parent_start:
            parent_start = parent
        parents[parent_start] = child

    # Cycle detection in the tree structure
    def cycle_detection(ancestor, parent):
        return ancestor if not parents[ancestor] else cycle_detection(parents[ancestor], ancestor)

    while cycle_detection(parent_start, 0) != -1:
        parent = cycle_detection(parent_start, 0)
        tree[parent] += 1

    # Ensure we started from 0 and end in n-1
    for i in range(1, n):
        if tree[i] == 0:
            tree[i] = 10 ** 5 - i - 1
        elif tree[i] == 1:
            tree[i] = 10 ** 5 - i
    return tuple(tree)

def solve(n, parents):
    return solve_tree(n, parents)

