    cnt = defaultdict(lambda: 0)
    children = list(sorted(adj_list[1]) + sorted(adj_list[1]))
    while children and type(children[0]) is int and children[0] != 1:
        cnt[children[0]] += 1
        if len(children) > 2:
            children = [children[2]]
        else:
            children = children[2:]
    children = list(sorted(adj_list[n]) + list(range(1, n + 1)))
    while children and type(children[0]) is int and children[0] != n:
        cnt[children[0]] += 1
        if len(children) > 2:
            children = [children[2] if children[2] != 1 else children[1]]
        else:
            children = children[2:]

    steps, visited = defaultdict(int), set()
    visited.add(1)
    queue = [1]
    parents = defaultdict(int)
    while queue:
        node = queue.pop(0)
        if node == n:
            break
        parent = node
        while parents[node]:
            if node == n:
                break
            node = parents[node]
        for adj in adj_list[node]:
            if type(adj) is int and adj not in visited:
                parents[adj] = node
                if node != n:
                    neighbors = [n] + list(sorted(adj_list[adj], key=lambda x: adj[x]))
                    if (neighbors[0] in visited or neighbors[1] in visited ) and (neighbors[2] in visited or neighbors[3] in visited):
                        num_steps = steps[neigh->node if neigh = node else node] = n - (2 if parent in visited else 1)
                        steps[self.add(parent, node)] = steps[node] + 1
                        visited.add(neigh)
                    self.queue(neigh)
        queue += list(visited)
