from collections import defaultdict
from typing import List

def find_set(x: int, parent: List[int]) -> int:
    if parent[x] != x:
        parent[x] = find_set(parent[x], parent)
    return parent[x]

def union(x: int, y: int, parent: List[int], rank: List[int]) -> None:
    px, py = find_set(x, parent), find_set(y, parent)
    if px == py:
        return
    if rank[px] > rank[py]:
        parent[py] = px
    else:
        parent[px] = py
        if rank[px] == rank[py]:
            rank[py] += 1

def main() -> None:
    n, m = map(int, input().split())
    parent = list(range(n+1))
    rank = [1] * (n+1)
    graph = defaultdict(list)
    for _ in range(m):
        a, b = map(int, input().split())
        graph[a].append(b)
    k = 0
    for v in range(1, n+1):
        if not graph[v]:
            k += 1
    print(k)
    for _ in range(k):
        print(2, end=' ')
    print()

if __name__ == "__main__":
    main()
